function validate([basket1, basket2]) {
  if (basket1.length !== basket2.length) return 'Both baskets must hold the same number of fruits.';
  if (basket1.length < 1 || basket1.length > 100000) return 'Each basket holds 1 to 10^5 fruits.';
  for (const v of [...basket1, ...basket2]) {
    if (!Number.isInteger(v) || v < 1 || v > 1000000000) return 'Each cost is a whole number from 1 to 10^9.';
  }
  return null;
}

