function minCost(basket1, basket2) {
  // balance[cost] = copies in basket1 minus copies in basket2.
  const balance = new Map();
  let smallest = Infinity;
  for (const fruit of basket1) {
    balance.set(fruit, (balance.get(fruit) ?? 0) + 1);
    smallest = Math.min(smallest, fruit);
  }
  for (const fruit of basket2) {
    balance.set(fruit, (balance.get(fruit) ?? 0) - 1);
    smallest = Math.min(smallest, fruit);
  }

  // Each basket must give away half of its surplus of every cost.
  const extra = [];
  for (const [fruit, diff] of balance) {
    if (diff % 2 !== 0) {
      return -1;
    }
    for (let i = 0; i < Math.abs(diff) / 2; i++) {
      extra.push(fruit);
    }
  }

  // Pair cheap misplaced fruits with expensive ones; the cheap half pays.
  extra.sort((a, b) => a - b);
  let cost = 0;
  for (let i = 0; i < extra.length / 2; i++) {
    cost += Math.min(extra[i], 2 * smallest);
  }
  return cost;
}

