function minCost(basket1, basket2) {
  // Dijkstra over the sorted contents of basket1; basket2 is whatever is left.
  const byValue = (a, b) => a - b;
  const all = [...basket1, ...basket2].sort(byValue);
  const rest = (one) => {
    const left = [...all];
    for (const v of one) left.splice(left.indexOf(v), 1);
    return left;
  };
  const start = [...basket1].sort(byValue);
  const dist = new Map([[start.join(','), 0]]);
  const states = new Map([[start.join(','), start]]);
  const done = new Set();
  for (;;) {
    let current = null;
    for (const [key, d] of dist) {
      if (!done.has(key) && (current === null || d < dist.get(current))) current = key;
    }
    if (current === null) return -1;
    done.add(current);
    const one = states.get(current);
    const two = rest(one);
    if (one.join(',') === two.join(',')) return dist.get(current);
    for (let i = 0; i < one.length; i++) {
      for (let j = 0; j < two.length; j++) {
        const next = [...one];
        next[i] = two[j];
        next.sort(byValue);
        const key = next.join(',');
        const d = dist.get(current) + Math.min(one[i], two[j]);
        if (!dist.has(key) || d < dist.get(key)) {
          dist.set(key, d);
          states.set(key, next);
        }
      }
    }
  }
}

