function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const shuffle = (a) => {
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const large = size === 'large';
  const n = large ? 2000 : int(1, 5);
  const top = large ? [50, 1000000000][int(0, 1)] : int(2, 8);
  if (!large && rand() < 0.25) {
    // Independent random baskets: often impossible, sometimes not.
    return [Array.from({ length: n }, () => int(1, top)), Array.from({ length: n }, () => int(1, top))];
  }
  // Every cost appears an even number of times in total, so the baskets can be made equal.
  const pool = Array.from({ length: n }, () => int(1, top));
  const items = shuffle([...pool, ...pool]);
  const basket1 = items.slice(0, n);
  const basket2 = items.slice(n);
  if (rand() < 0.15) basket1[int(0, n - 1)] = top + 1;
  return [basket1, basket2];
}
